class Soedinenie(sqlite3.Connection):
    """Own the process queue only while a write transaction is active."""

    def _pered_zapisyu(self, sql):
        if not _ua_sql_pishet(sql) or getattr(self, "_ua_zapis_v_ocheredi", False):
            return False
        vzyata = ZAMOK.acquire(timeout=ZAMOK_OZHIDANIE)
        if not vzyata:
            raise sqlite3.OperationalError("CRM thread queue timeout")
        self._ochered_vzyata = True
        try:
            _ua_fayl_zahvatit(ZAMOK_OZHIDANIE)
            self._fayl_zaregistrirovan = True
            self._ua_zapis_v_ocheredi = True
            return True
        except Exception:
            self._ochered_vzyata = False
            try:
                ZAMOK.release()
            except Exception:
                pass
            raise

    def _otpustit(self):
        self._ua_zapis_v_ocheredi = False
        if getattr(self, "_fayl_zaregistrirovan", False):
            self._fayl_zaregistrirovan = False
            try:
                _ua_fayl_otpustit()
            except Exception:
                pass
        if getattr(self, "_ochered_vzyata", False):
            self._ochered_vzyata = False
            try:
                ZAMOK.release()
            except Exception:
                pass

    def cursor(self, factory=None):
        return sqlite3.Connection.cursor(self, factory or _UaKursor)

    def execute(self, sql, parameters=()):
        novaya = self._pered_zapisyu(sql)
        try:
            return sqlite3.Connection.execute(self, sql, parameters)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def executemany(self, sql, seq_of_parameters):
        novaya = self._pered_zapisyu(sql)
        try:
            return sqlite3.Connection.executemany(self, sql, seq_of_parameters)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def executescript(self, sql_script):
        novaya = self._pered_zapisyu(sql_script)
        try:
            return sqlite3.Connection.executescript(self, sql_script)
        except Exception:
            if novaya and not self.in_transaction:
                self._otpustit()
            raise

    def _commit_s_povtorom(self):
        import time as _ua_time

        for attempt in range(5):
            try:
                sqlite3.Connection.commit(self)
                return
            except sqlite3.OperationalError as exc:
                text = str(exc).casefold()
                if "locked" not in text and "busy" not in text:
                    raise
                if attempt == 4:
                    raise
                _ua_time.sleep(0.15 * (2 ** attempt))

    def commit(self):
        try:
            self._commit_s_povtorom()
        except Exception:
            try:
                sqlite3.Connection.rollback(self)
            finally:
                self._otpustit()
            raise
        self._otpustit()

    def rollback(self):
        try:
            return sqlite3.Connection.rollback(self)
        finally:
            self._otpustit()

    def close(self):
        try:
            if self.in_transaction:
                sqlite3.Connection.rollback(self)
            sqlite3.Connection.close(self)
        finally:
            self._otpustit()

    def __exit__(self, tip, znachenie, sled):
        try:
            if tip is None:
                self.commit()
            else:
                self.rollback()
        finally:
            try:
                self.close()
            except Exception:
                self._otpustit()
        return False

    def __del__(self):
        self._otpustit()

def connect():
    conn = sqlite3.connect(DB_FILE, timeout=ZAMOK_OZHIDANIE, factory=Soedinenie)
    conn.row_factory = sqlite3.Row
    # Setup pragmas must not hold the transaction queue for a long-lived reader.
    try:
        sqlite3.Connection.execute(conn, "PRAGMA journal_mode=DELETE")
    except Exception:
        pass
    sqlite3.Connection.execute(
        conn, "PRAGMA busy_timeout=%d" % (ZAMOK_OZHIDANIE * 1000)
    )
    sqlite3.Connection.execute(conn, "PRAGMA foreign_keys=ON")
    return conn

def card_of(card_id):
    card = db.get_card("cars", int(card_id))
    if not card:
        return None
    # старые значения подтягиваем в новые поля, если новые пустые
    for old, new in LEGACY.items():
        if not card.get(new) and card.get(old):
            card[new] = card[old]
    return card

def set_field(card_id, field, value, actor_id):
    """Пустое значение в карточку не пишем — данные не теряются."""
    if value in (None, "", []):
        return
    db.update_card_field("cars", int(card_id), field, value, actor_id)

def apply_value(card_id, field, raw, actor_id):
    """Возвращает (ок, сообщение). Ничего не додумывает."""
    value = (raw or "").strip()
    if not value:
        return False, "Пустое значение не записываю."

    if field == "eta_days":
        digits = "".join(ch for ch in value if ch.isdigit())
        if not digits:
            return False, "Пришлите число дней, например 45."
        n = int(digits)
        if n > 400:
            return False, "Слишком большой срок. Пришлите число дней."
        eta = _date.today() + _td(days=n)
        set_field(card_id, "eta_manual", eta.isoformat(), actor_id)
        set_field(card_id, "days_to_kyiv", n, actor_id)
        return True, "До прибытия %d дней · %s" % (n, eta.strftime("%d.%m.%Y"))

    if field in NUMERIC:
        digits = value.lower().replace(" ", "").replace("\u00a0", "")
        for lishnee in ("цена", "стоимость", "$", "usd", "долларов", "долл"):
            digits = digits.replace(lishnee, "")
        for word, mult in (("тысяч", 1000), ("тыс", 1000), ("к", 1000)):
            if word in digits.lower():
                digits = digits.lower().split(word)[0]
                try:
                    num = int(float(digits.replace(",", ".")) * mult)
                except ValueError:
                    return False, "Не разобрал число. Пришлите цифрами."
                break
        else:
            digits = "".join(ch for ch in digits if ch.isdigit())
            if not digits:
                return False, "Не разобрал число. Пришлите цифрами."
            num = int(digits)
        if field == "engine_cc" and num < 100:
            return False, ("Похоже, это литры. Объём нужен в кубических сантиметрах — "
                           "например, 1598.")
        set_field(card_id, field, num, actor_id)
        return True, "Записано: %s" % S.num(num)

    if field == "vin":
        vin = value.upper().replace(" ", "")
        ok, msg = S.check_vin(vin)
        if not ok:
            return False, "VIN не принят: %s" % msg
        set_field(card_id, field, vin, actor_id)
        return True, "Записано: %s" % vin

    set_field(card_id, field, value, actor_id)
    return True, "Записано."

def _v168_cas_write(card_id, field, expected_old, new_value, actor_id, correction=False):
    import re as _v168_re
    if not _v168_re.fullmatch(r"[a-z_][a-z0-9_]*", str(field or "")):
        return False, "invalid"
    if _v168_empty(new_value):
        return False, "empty"
    with db.connect() as _v168_con:
        columns = {row[1] for row in _v168_con.execute("PRAGMA table_info(cars)")}
        if field not in columns:
            return False, "unknown"
        row = _v168_con.execute(
            "SELECT %s FROM cars WHERE id=?" % field, (int(card_id),)).fetchone()
        if row is None:
            return False, "missing_card"
        current = row[0]
        if str(current or "") == str(new_value):
            return False, "same"
        if correction:
            if str(current or "") != str(expected_old or ""):
                return False, "conflict"
        elif not _v168_empty(current):
            return False, "filled"
        cursor = _v168_con.execute(
            "UPDATE cars SET %s=?,updated_at=? WHERE id=? AND %s IS ?" % (field, field),
            (new_value, db.now(), int(card_id), current))
        if cursor.rowcount != 1:
            return False, "conflict"
    try:
        db.log_action(actor_id, "card_edit", "cars", int(card_id),
                      field, current, new_value)
    except Exception as _v168_exc:
        log.warning("CRM CAS audit failed card=%s field=%s error=%s",
                    card_id, field, _v168_exc)
    return True, "applied"

def voice_change_plan(card, data, allowed, override=False):
    """Return bounded field updates; filled values change only by explicit request."""
    changes = []
    skipped = []
    permitted = set(allowed or ())
    for field, value in (data or {}).items():
        if field not in permitted or value in (None, "", []):
            continue
        old = card.get(field)
        if old not in (None, "", 0, []) and not override:
            skipped.append(field)
            continue
        if str(old or "") != str(value):
            changes.append((field, old, value))
    return changes, skipped

def _v167_voice_explicit_fields(text, allowed):
    """Deterministic RU/UA/EN automotive fields; ambiguous input writes nothing."""
    import re as _v167_re
    value = str(text or "").casefold().replace("ё", "е")
    for words in ("две тысячи", "дві тисячі", "дві тисячі", "two thousand"):
        value = value.replace(words, "2000")
    result, permitted = {}, set(allowed or ())
    if "fuel" in permitted:
        fuel = None
        if _v167_re.search(r"(?<![a-zа-яіїєґ0-9])(?:l\s*p\s*i|л\s*п\s*и|[еэ]л\s*пи\s*ай)(?![a-zа-яіїєґ0-9])", value):
            fuel = "LPI"
        elif _v167_re.search(r"(?<![a-zа-яіїєґ0-9])(?:l\s*p\s*g|л\s*п\s*г|[еэ]л\s*пи\s*джи)(?![a-zа-яіїєґ0-9])", value):
            fuel = "LPG"
        elif _v167_re.search(r"\b(?:дизел[ьяь]?|дизельне|diesel)\b", value):
            fuel = "diesel"
        elif _v167_re.search(r"\b(?:бензин|бензинов|gasoline|petrol)\b", value):
            fuel = "gasoline"
        elif _v167_re.search(r"\b(?:гибрид|гібрид|hybrid)\b", value):
            fuel = "hybrid"
        elif _v167_re.search(r"\b(?:электро|електро|electric)\b", value):
            fuel = "electric"
        elif _v167_re.search(r"(?:топлив|палив|fuel)\s*(?:[:=\-–—]|тип)?\s*газ\b", value):
            fuel = "LPG"
        if fuel:
            result["fuel"] = fuel
    if "engine_cc" in permitted:
        label = r"(?:объ?ем(?:\s+двигателя)?|об['’]?єм(?:\s+двигуна)?|двигател[ья]|двигун[ау]?|мотор[ау]?|engine(?:\s+volume)?)"
        match = (_v167_re.search(label + r"\s*(?:[:=\-–—]|составляет|становить|is)?\s*(\d+(?:[.,]\d+)?)", value)
                 or _v167_re.search(r"(\d+(?:[.,]\d+)?)\s*(?:см3|см³|cc|куб(?:ов)?)?\s*" + label, value))
        if match:
            try:
                number = float(match.group(1).replace(",", "."))
                cc = int(round(number * 1000 if number < 20 else number))
                if 400 <= cc <= 12000:
                    result["engine_cc"] = cc
            except Exception:
                pass
    if "color" in permitted:
        colors = {
            "бел": "белый", "білий": "белый", "біла": "белый", "white": "белый",
            "черн": "чёрный", "чорн": "чёрный", "black": "чёрный",
            "серебр": "серебристый", "сріб": "серебристый", "silver": "серебристый",
            "сер": "серый", "сір": "серый", "gray": "серый", "grey": "серый",
            "красн": "красный", "червон": "красный", "red": "красный",
            "син": "синий", "blue": "синий", "зелен": "зелёный", "green": "зелёный",
            "желт": "жёлтый", "жовт": "жёлтый", "yellow": "жёлтый",
            "беж": "бежевый", "beige": "бежевый", "корич": "коричневый", "brown": "коричневый",
        }
        match = _v167_re.search(
            r"(?:(?:цвет|колір|color)\s*(?:[:=\-–—]|автомобиля|авто|машины|car)?\s*([a-zа-яіїєґ]+)|"
            r"([a-zа-яіїєґ]+)\s+(?:цвет|колір|color))", value)
        if match:
            word = next((item for item in match.groups() if item), "")
            for prefix, normalized in colors.items():
                if word.startswith(prefix):
                    result["color"] = normalized
                    break
    return result

class _UaSoedinenie(sqlite3.Connection):
    def __init__(self, *a, **kw):
        sqlite3.Connection.__init__(self, *a, **kw)
        self._ua_baza = os.path.basename(str(a[0] if a else kw.get("database", "?")))
        self._ua_svoya = CEL in self._ua_baza
        self._ua_id = _novyy_id()
        self._ua_t0 = time.time()
        self._ua_kto = _kto(3)
        if self._ua_svoya:
            _dobavit(self._ua_id, self._ua_kto, self._ua_baza, self)
            _zapis("OPEN " + self._ua_id, 0.0, self._ua_baza + " | " + self._ua_kto)

    def commit(self):
        t0 = time.time()
        busy = "?"
        if self._ua_svoya:
            try:
                busy = self.execute("PRAGMA busy_timeout").fetchone()[0]
            except Exception:
                pass
        try:
            sqlite3.Connection.commit(self)
        except Exception as e:
            d = time.time() - t0
            _zapis("COMMIT_FAIL", d, self._ua_baza + " | " + self._ua_kto + " | " + repr(e))
            if self._ua_svoya:
                otchet_o_sboe(d, e, self._ua_kto, busy)
            raise
        d = time.time() - t0
        if self._ua_svoya:
            _zapis("COMMIT_OK " + self._ua_id, d, self._ua_kto)

    def close(self):
        try:
            if self._ua_svoya:
                _ubrat(self._ua_id)
                _zapis("CLOSE " + self._ua_id, time.time() - self._ua_t0, self._ua_kto)
        except Exception:
            pass
        sqlite3.Connection.close(self)

def _ua_connect(*a, **kw):
    if len(a) < 2 and "timeout" not in kw:
        kw["timeout"] = 30.0
    kw.setdefault("factory", _UaSoedinenie)
    con = _originalnyy_connect(*a, **kw)
    try:
        con.execute("PRAGMA busy_timeout=30000")
    except Exception:
        pass
    return con

def podklyuchit(g):
    try:
        ishodnyy = g.get("connect")
        if not callable(ishodnyy) or getattr(ishodnyy, "_ua_trace", False):
            return False

        def connect_s_trassoy(*a, **kw):
            return _Obertka(ishodnyy(*a, **kw), _kto(3))

        connect_s_trassoy._ua_trace = True
        connect_s_trassoy._ua_ishodnyy = ishodnyy
        g["connect"] = connect_s_trassoy
        _zapis("PODKLYUCHEN", 0.0, "db.connect обёрнут (V2)")
        return True
    except Exception as e:
        _zapis("PODKLYUCHENIE_FAIL", 0.0, repr(e))
        return False
